import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    # Windowed statistics
    window = history[-12:] if n >= 12 else history
    w = len(window)
    opp_c_recent = sum(1 for _, o in window if o == 'C')
    opp_d_recent = w - opp_c_recent
    my_c_recent = sum(1 for m, _ in window if m == 'C')

    opp_c_total = sum(1 for o in opp if o == 'C')
    opp_d_total = n - opp_c_total

    last_me = my[-1]
    last_opp = opp[-1]

    # Detect pure strategies early
    if opp_d_total == 0:
        # Always cooperates: exploit near end, otherwise mostly cooperate
        if n >= 92:
            return 'D'
        # Periodic slight exploitation to gain extra
        if n >= 20 and n % 7 == 0:
            return 'D'
        return 'C'

    if opp_c_total == 0:
        return 'D'

    # Cooperation rates
    recent_rate = opp_c_recent / w
    total_rate = opp_c_total / n

    # Detect alternation / periodic patterns briefly
    if n >= 6:
        last6 = opp[-6:]
        if last6 == ['C', 'D'] * 3:
            # opponent alternates; play opposite to capture DC on their D turn
            # their next likely: after D comes C
            return 'D' if last_opp == 'C' else 'C'
        if last6 == ['D', 'C'] * 3:
            return 'D' if last_opp == 'C' else 'C'

    # Mutual defection recovery: break DD loops
    if n >= 3:
        last3 = history[-3:]
        if all(m == 'D' and o == 'D' for m, o in last3):
            return 'C'

    # Strong recent defection -> punish
    if opp_d_recent >= 7:
        return 'D'

    # Strong recent cooperation -> cooperate
    if opp_d_recent <= 1:
        # But probe occasionally against very cooperative opponents
        if n >= 30 and opp_d_total <= 2 and recent_rate >= 0.9:
            if n % 9 == 0:
                return 'D'
        return 'C'

    # Opponent defected last round
    if last_opp == 'D':
        # If total defection rate is low, forgive often
        if total_rate >= 0.7:
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        # If we're in a mutual defection streak, probe cooperation
        if last_me == 'D':
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # We cooperated, they defected
        if total_rate >= 0.45:
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_opp == 'C':
        # If we defected and they still cooperated, they're forgiving; exploit occasionally
        if last_me == 'D':
            if total_rate >= 0.6 and rng.random() < 0.5:
                return 'D'
            return 'C'
        # Standard cooperative response
        if recent_rate >= 0.5:
            return 'C'
        # Mid-range: sometimes defect to test
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    return 'C'
